import axios from "axios";

const TAGS_ENDPOINT = "/api/tags";

async function fetchTags(signal) {
  const { data } = await axios.get(TAGS_ENDPOINT, { signal });

  return Array.isArray(data?.tags) ? data.tags : [];
}

export { fetchTags };

import StatusMessage from "./StatusMessage";

const MAX_TAGS = 50;

function renderTags(tags) {
  return (
    <ul className="tag-list-items">
      {tags.slice(0, MAX_TAGS).map((name) => (
        <li key={name}>
          <button className="tag-pill tag-default" type="button">
            {name}
          </button>
        </li>
      ))}
    </ul>
  );
}

function PopularTagsView({ tags, loading, error }) {
  let content = <StatusMessage>Tags list not available</StatusMessage>;

  if (loading) {
    content = <StatusMessage>Loading tags...</StatusMessage>;
  } else if (error) {
    content = <StatusMessage>{error}</StatusMessage>;
  } else if (tags.length > 0) {
    content = renderTags(tags);
  }

  return (
    <aside className="col-md-3">
      <div className="sidebar">
        <h6>Popular Tags</h6>
        <div className="tag-list">{content}</div>
      </div>
    </aside>
  );
}

export default PopularTagsView;

function StatusMessage({ children }) {
  return <p>{children}</p>;
}

export default StatusMessage;
